/// <summary>
/// Class entry point. The system will call this method when a designated menu 
/// is selected or when execution starts and this class is set as the startup class.
/// </summary>
/// <param name = "_args">The specified arguments.</param>
public static void main(Args _args)
{
    OMGOutboundMessage message = new OMGOutboundMessage();

    message.parmMessageTypeId('out');
    message.parmMessageName('Test message');
    message.parmMessage('{ "Test": "Test message" }');

    Map metadata = message.parmMetadata();

    metadata.add('InvoiceId','123456');
    metadata.add('CustomerAccount','US-001');

    message.send();

}
